import { pgTable, serial, text, jsonb, timestamp } from "drizzle-orm/pg-core";

// The narrative sections of a country brief, generated by the AI prose engine
// (see artifacts/api-server/src/lib/countryProse.ts). implications and watchNext
// are bullet lists; the rest are paragraphs.
export interface CountryProseSections {
  executiveSummary: string;
  situation: string;
  whatHappened: string;
  whatMatters: string;
  implications: string[];
  watchNext: string[];
  polestarView: string;
  // Bottom-line-up-front and "what changed" narrative paragraphs. Only the
  // structured brief (variant "png") populates these; the generic country
  // report leaves them undefined. Each prefers the AI text and falls back to
  // the deterministic dataset paragraph when no AI prose exists.
  bluf?: string;
  whatChanged?: string;
  // Forward-looking outlook paragraph. Only the PNG country brief (variant
  // "png") populates this; the generic country report leaves it undefined.
  outlook?: string;
  // Per-incident analyst summaries for the structured brief (variant "png"),
  // keyed by incident id. Each is a short factual summary grounded only on that
  // incident's own title + summary. Cached/edited with the rest of the sections;
  // absent for the generic country report.
  incidentSummaries?: Record<string, string>;
}

// Cache of AI-generated country-report prose, keyed one-row-per-country.
//
// `fingerprint` is a hash of the exact window incidents the prose was grounded
// on (plus the prompt version). When the underlying data changes the
// fingerprint changes and the prose is regenerated. `edited` holds analyst
// overrides. Unlike the earlier model — where a regenerate dropped `edited` so
// an edit could never outlive its data snapshot — an analyst edit is now KEPT
// across a regenerate: `editedFingerprint` records the fingerprint the edit was
// written against, so when the data basis moves on the edit is retained and the
// client surfaces a staleness warning (edit stays, is never silently discarded)
// rather than being overwritten by fresh AI prose.
export const countryReportProseTable = pgTable("country_report_prose", {
  id: serial("id").primaryKey(),
  slug: text("slug").notNull().unique(),
  fingerprint: text("fingerprint").notNull(),
  sections: jsonb("sections").$type<CountryProseSections>().notNull(),
  edited: jsonb("edited").$type<CountryProseSections | null>(),
  // The fingerprint the current `edited` override was written against. When it
  // differs from `fingerprint`, the edit predates the current data basis and is
  // stale (kept, but flagged to the analyst). NULL when there is no edit.
  editedFingerprint: text("edited_fingerprint"),
  model: text("model").notNull(),
  generatedAt: timestamp("generated_at", { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type CountryReportProse = typeof countryReportProseTable.$inferSelect;
export type InsertCountryReportProse = typeof countryReportProseTable.$inferInsert;
